import Foundation

enum TaskStatus { case open, complete }
struct TaskItem {
    let id: UUID
    var title: String
    var category: String
    var status: TaskStatus
}

func completedCount(_ tasks: [TaskItem]) -> Int { tasks.filter { $0.status == .complete }.count }
func filter(_ tasks: [TaskItem], category: String) -> [TaskItem] {
    tasks.filter { $0.category.localizedCaseInsensitiveCompare(category) == .orderedSame }
}

let tasks = [TaskItem(id: UUID(), title: "Read", category: "Study", status: .complete), TaskItem(id: UUID(), title: "Walk", category: "Health", status: .open)]
print("Completed: \(completedCount(tasks))")
print("Study tasks: \(filter(tasks, category: "study").count)")
